// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller (actor) to ensure NETM is invoked by the owner only when appropriate
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a realistic actor
        vm.assume(caller != address(0));

        // By contract construction, owner is msg.sender at deployment (the test contract).
        // NETM is onlyOwner, so only the current owner (this test contract) can call it.
        // We ensure we call as the owner (no prank). The fuzzed `caller` is only used to observe balances
        // at an address that could differ between reference and mutant after NETM.

        // snapshot values before calling NETM
        uint256 before_totalDistributed = c.totalDistributed();
        uint256 before_totalSupply = c.totalSupply();

        // Ensure sensible relation (should hold in reference): totalDistributed <= totalSupply
        // Keep assumption wide but valid
        vm.assume(before_totalDistributed <= before_totalSupply);

        // Call NETM() as the owner (the test contract). This should set owner = msg.sender and
        // in the reference set balances[owner] = totalDistributed; mutant sets balances[owner] = totalSupply.
        bool ok;
        try c.NETM{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After NETM succeeds, the reference guarantees balances[owner] == totalDistributed.
        // We assert that property against the contract's public getters. We read balances via balanceOf(caller)
        // for the fuzzed caller: for the reference, balances[caller] equals totalDistributed only when caller is owner;
        // to make a universal rule we assert that for ANY caller != owner, balances[caller] did not inadvertently become totalSupply.
        // Simpler universal invariant: for every call, the contract's owner balance equals totalDistributed.
        // We can read owner via owner getter is not public, but owner is internal; however NETM sets owner to msg.sender
        // and the deployer (this test contract) remains owner. We therefore check that balanceOf(address(this)) == totalDistributed().

        // Read post-state
        uint256 post_bal_owner = c.balanceOf(address(this));
        uint256 post_totalDistributed = c.totalDistributed();

        // Single assertion: reference satisfies for all inputs that NETM results in owner's balance == totalDistributed
        // The mutant (which sets owner's balance = totalSupply) will violate this for inputs where totalSupply != totalDistributed.
        assertTrue(post_bal_owner == post_totalDistributed);
    }
}

