pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and an arbitrary extra uint to keep domain wide
    function testFuzz_property(address caller, uint256 dummy) public {
        // keep caller as non-zero
        vm.assume(caller != address(0));

        // Ensure caller is the owner: the contract sets owner = msg.sender at construction,
        // which in setUp() was the test address; we must act as that owner when calling NETM.
        // get the address that deployed c in setUp(): it's address(this) in the test environment,
        // so use vm.prank(address(this)) to call NETM. To be defensive, ensure caller isn't used as owner.

        // capture owner's address via behavior: owner is the test contract (address(this)) after setUp
        address owner = address(this);

        // read totalDistributed before calling NETM
        uint256 beforeDistributed = c.totalDistributed();
        // read owner's balance before calling NETM
        uint256 beforeBalance = c.balanceOf(owner);

        // Sanity: in reference contract constructor behaviour, balances[owner] should equal totalDistributed
        // but we don't assert that here; instead we check NETM preserves balances.

        // Call NETM() as owner
        vm.prank(owner);
        // NETM is non-payable and onlyOwner, call it and catch revert if any
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, read owner's balance
        uint256 afterBalance = c.balanceOf(owner);
        uint256 afterDistributed = c.totalDistributed();

        // General invariant: For the correct contract, calling NETM() by the owner leaves the owner's balance equal to totalDistributed (the initial distribution assigned to owner remains); thus owner's balance should remain equal to totalDistributed and unchanged by NETM.
        // We assert this universal property by checking that owner's balance equals totalDistributed after the call AND that it did not change from before. This is one assertTrue reading public getters of c.
        assertTrue(afterBalance == afterDistributed && afterBalance == beforeBalance && ok);
    }
}

