pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address that will be set as owner via transferOwnership, and a uint that we use to manipulate balances via distr through getTokens
    function testFuzz_property(address newOwner, uint256 nCalls) public {
        // keep domain reasonable: newOwner must be non-zero and not the initial owner
        vm.assume(newOwner != address(0));
        // bound nCalls to a moderate range so test runs quickly but still explores behavior
        nCalls = bound(nCalls, 0, 10);

        // ensure some ether to perform getTokens calls
        vm.deal(address(this), 1 ether);

        // initial owner is the deployer (this contract in setUp is msg.sender there), but in tests msg.sender is this test contract.
        // Transfer ownership to newOwner to create a scenario where NETM called by newOwner matters.
        // first, call transferOwnership as the current owner (test contract)
        c.transferOwnership(newOwner);

        // Now simulate some distributions to newOwner by invoking getTokens from different addresses to change totalDistributed and balances
        // We need addresses that are not blacklisted initially. Use address(1..n)
        for (uint256 i = 0; i < nCalls; i++) {
            address actor = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp)))));
            vm.deal(actor, 1e15);
            vm.prank(actor);
            // call getTokens to cause distr and set blacklist for that actor
            // ignore reverts if distribution finished
            try c.getTokens{value: 1e15}() {
            } catch {
            }
        }

        // Capture owner's balance and totalDistributed before NETM
        uint256 beforeBal;
        uint256 totalDistBefore;
        // owner is newOwner now
        beforeBal = c.balanceOf(newOwner);
        totalDistBefore = c.totalDistributed();

        // Now call NETM as the owner (newOwner). According to reference NETM sets owner=msg.sender and sets balances[owner]=totalDistributed.
        vm.prank(newOwner);
        // we wrap in try/catch to be robust, but NETM should not revert; still we capture success.
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // After NETM, reference contract guarantees balances[newOwner] == totalDistributed.
        // Single assertion: check that balances[newOwner] equals totalDistributed (this holds for reference for all inputs; mutant that removed the assignment can violate it).
        assertTrue(c.balanceOf(newOwner) == c.totalDistributed());
    }
}

