pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller (owner candidate) and an unrelated extra address to keep fuzzer wide
    function testFuzz_property(address callerAddr, address other) public {
        // keep callerAddr non-zero to be a valid address
        vm.assume(callerAddr != address(0));

        // The contract constructor set owner = msg.sender, which is this test contract.
        // But NETM is onlyOwner, so only the current owner (this test contract) can call it.
        // We will call NETM as the owner (no prank) and then check the invariant.

        // Read totalDistributed before calling
        uint256 td_before = c.totalDistributed();

        // Call NETM as owner (this test contract is owner because it deployed c in setUp)
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: after NETM completes successfully (ok==true),
        // the owner's balance equals totalDistributed. The reference satisfies this for all inputs;
        // the mutant (which sets balances[owner]=0) will violate it for some inputs (when totalDistributed>0).
        // We must produce exactly one assertTrue that reads c's public surface.

        // If NETM reverted, the universal property (that NETM succeeds for owner) is not required by the spec,
        // but the key invariant we check only when the call succeeded. To keep a single assert, we
        // assert that either NETM reverted (ok==false) OR balances(owner) == totalDistributed.
        // This assertion is always true for the reference (NETM does not revert and sets balances[owner]==totalDistributed),
        // and will fail on the mutant for some inputs because it leaves balances[owner]==0 while totalDistributed>0.

        address owner = address(this);
        uint256 ownerBal = c.balanceOf(owner);
        uint256 td_after = c.totalDistributed();

        // Single assertion required by the task: the reference satisfies (ok implies ownerBal==td_after)
        assertTrue(!ok || ownerBal == td_after);
    }
}

