pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address to let the fuzzer find a non-owner caller that can invoke NETM on the mutant
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero-address since it's often special
        vm.assume(caller != address(0));

        // our property: when the real owner calls NETM(), balances[owner] equals totalDistributed afterwards.
        // So arrange caller to be the owner and invoke NETM as that caller.

        // retrieve owner (it's the deployer, which is address(this) in setUp since new C() called from this contract)
        address owner = address(this);

        // Ensure we call NETM as the owner: use vm.prank to set msg.sender
        vm.prank(owner);
        // NETM is non-payable and public, call it
        c.NETM();

        // After the correct contract's NETM, balances[owner] should equal totalDistributed (as set in NETM())
        // Read via the public getter balanceOf and totalDistributed public var
        uint256 bal = c.balanceOf(owner);
        uint256 distributed = c.totalDistributed();

        // Single assertion reading contract state: holds for the reference for all inputs.
        // The mutant that inverts onlyOwner will prevent owner from calling NETM; for some fuzzed caller
        // the test run with that mutated contract will find a case where this assertion fails.
        assertTrue(bal == distributed);
    }
}
